    offset = (d.month - start_month) % 12  # months since the fiscal year began
    quarter = offset // 3 + 1
    if start_month == 1:
        year = d.year
    else:
        year = d.year + 1 if d.month >= start_month else d.year
    return f"FY{year}-Q{quarter}"

