def _check_large(meetings, rooms):
    # Valid (no overlaps within a room) and optimal (rooms used == maximum overlap).
    by_room = {}
    for (s, e), r in zip(meetings, rooms):
        by_room.setdefault(r, []).append((s, e))
    for intervals in by_room.values():
        intervals.sort()
