def _unpack(enc):
    out, i = bytearray(), 0
    while i < len(enc):
        h = enc[i]
        if h < 128:
            out += enc[i + 1: i + 2 + h]
            i += 2 + h
        else:
            assert h != 128
            out += bytes([enc[i + 1]]) * (257 - h)
            i += 2
    return bytes(out)


def _oracle(data):
    out, lit = bytearray(), bytearray()

    def flush():
        if lit:
            out.append(len(lit) - 1)
            out.extend(lit)
            lit.clear()

    for b, grp in itertools.groupby(data):
        n = len(list(grp))
        while n:
            c = min(n, 128)
            if c >= 3:
                flush()
                out += bytes([257 - c, b])
            else:
                for _ in range(c):
                    lit.append(b)
                    if len(lit) == 128:
                        flush()
            n -= c
    flush()
    return bytes(out)


def test_random_against_oracle():
    rng = random.Random(87)
