        mtype, slash, subtype = media.strip(_OWS).partition("/")
        if not slash or not _TOKEN.fullmatch(mtype) or not _TOKEN.fullmatch(subtype):
            raise ValueError(f"bad media range: {media!r}")
        if mtype == "*" and subtype != "*":
            raise ValueError(f"bad media range: {media!r}")
